import React, { useEffect, useState } from "react";

function Dashboard() {
  const [resumes, setResumes] = useState([]);

  useEffect(() => {
    fetchResumes();
  }, []);

  const fetchResumes = async () => {
    try {
      const token = localStorage.getItem("token");

      const res = await fetch("http://localhost:5000/api/resume/my", {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await res.json();
      setResumes(data);
    } catch (err) {
      console.error(err);
    }
  };

  const handleDelete = async (id) => {
    try {
      const token = localStorage.getItem("token");

      await fetch(`http://localhost:5000/api/resume/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      fetchResumes();
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <h1 style={styles.logo}>CareerForge Pro 🚀</h1>

        <div style={styles.actions}>
          <button
            style={styles.primaryBtn}
            onClick={() => (window.location.href = "/")}
          >
            + Analyze
          </button>

          <button
            style={styles.logoutBtn}
            onClick={() => {
              localStorage.removeItem("token");
              window.location.href = "/login";
            }}
          >
            Logout
          </button>
        </div>
      </div>

      <h2 style={styles.title}>Your Saved Resumes</h2>

      {resumes.length === 0 ? (
        <p style={styles.empty}>No resumes yet</p>
      ) : (
        <div style={styles.grid}>
          {resumes.map((item) => (
            <div key={item._id} style={styles.card}>
              
              <div style={styles.cardTop}>
                <span style={styles.score}>ATS {item.atsScore}</span>
              </div>

              <div style={styles.resume}>
                {item.resume}
              </div>

              <div style={styles.cardActions}>
                <button
                  style={styles.deleteBtn}
                  onClick={() => handleDelete(item._id)}
                >
                  Delete
                </button>
              </div>

            </div>
          ))}
        </div>
      )}
    </div>
  );
}

const styles = {
  page: {
    minHeight: "100vh",
    background: "linear-gradient(135deg, #0f172a, #020617)",
    padding: "30px",
    color: "#e2e8f0",
    fontFamily: "sans-serif",
  },

  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    marginBottom: "30px",
  },

  logo: {
    fontSize: "22px",
    fontWeight: "bold",
    color: "#38bdf8",
  },

  actions: {
    display: "flex",
    gap: "10px",
  },

  title: {
    marginBottom: "20px",
  },

  empty: {
    opacity: 0.6,
  },

  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))",
    gap: "20px",
  },

  card: {
    background: "rgba(255,255,255,0.05)",
    backdropFilter: "blur(10px)",
    border: "1px solid rgba(255,255,255,0.1)",
    borderRadius: "12px",
    padding: "15px",
    display: "flex",
    flexDirection: "column",
    transition: "0.3s",
  },

  cardTop: {
    display: "flex",
    justifyContent: "space-between",
    marginBottom: "10px",
  },

  score: {
    background: "#0ea5e9",
    padding: "5px 10px",
    borderRadius: "6px",
    fontSize: "12px",
  },

  resume: {
    background: "#020617",
    padding: "10px",
    borderRadius: "8px",
    height: "180px",
    overflowY: "auto",
    fontSize: "12px",
    whiteSpace: "pre-wrap",
    marginBottom: "10px",
  },

  cardActions: {
    marginTop: "auto",
  },

  primaryBtn: {
    background: "#0ea5e9",
    border: "none",
    padding: "10px 15px",
    borderRadius: "6px",
    color: "white",
    cursor: "pointer",
  },

  logoutBtn: {
    background: "#ef4444",
    border: "none",
    padding: "10px 15px",
    borderRadius: "6px",
    color: "white",
    cursor: "pointer",
  },

  deleteBtn: {
    width: "100%",
    background: "#f59e0b",
    border: "none",
    padding: "10px",
    borderRadius: "6px",
    cursor: "pointer",
    color: "#000",
    fontWeight: "bold",
  },
};

export default Dashboard;
